const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, HeadingLevel, BorderStyle, WidthType, ShadingType,
  VerticalAlign, PageBreak, LevelFormat, UnderlineType
} = require('docx');
const fs = require('fs');

const GOLD = "B8983A";
const DARK = "1A1A2E";
const MID = "3D3D5C";
const LIGHT_GOLD = "F9F4E8";
const LIGHT_GRAY = "F5F5F5";
const WHITE = "FFFFFF";

const noBorder = { style: BorderStyle.NONE, size: 0, color: "FFFFFF" };
const noBorders = { top: noBorder, bottom: noBorder, left: noBorder, right: noBorder };

function spacer(pt = 100) {
  return new Paragraph({ children: [], spacing: { before: pt, after: 0 } });
}

function goldRule() {
  return new Paragraph({
    children: [],
    border: { bottom: { style: BorderStyle.SINGLE, size: 12, color: GOLD, space: 1 } },
    spacing: { before: 0, after: 160 }
  });
}

function thinRule(color = "DDDDDD") {
  return new Paragraph({
    children: [],
    border: { bottom: { style: BorderStyle.SINGLE, size: 4, color: color, space: 1 } },
    spacing: { before: 0, after: 120 }
  });
}

// STAT BOX TABLE
function statBoxes() {
  const stats = [
    { num: "4", label: "Active Locations" },
    { num: "15+", label: "Years of Expertise" },
    { num: "200+", label: "NYC Competitors" },
    { num: "5.0", label: "Star Rating" }
  ];

  const cells = stats.map(s =>
    new TableCell({
      borders: noBorders,
      shading: { fill: DARK, type: ShadingType.CLEAR },
      width: { size: 2340, type: WidthType.DXA },
      margins: { top: 140, bottom: 140, left: 120, right: 120 },
      verticalAlign: VerticalAlign.CENTER,
      children: [
        new Paragraph({
          alignment: AlignmentType.CENTER,
          spacing: { before: 0, after: 40 },
          children: [new TextRun({ text: s.num, bold: true, size: 48, color: GOLD, font: "Arial" })]
        }),
        new Paragraph({
          alignment: AlignmentType.CENTER,
          spacing: { before: 0, after: 0 },
          children: [new TextRun({ text: s.label, size: 16, color: "CCCCCC", font: "Arial" })]
        })
      ]
    })
  );

  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [2340, 2340, 2340, 2340],
    rows: [new TableRow({ children: cells })]
  });
}

// COMPETITOR TABLE
function competitorTable() {
  const headerStyle = { fill: DARK, type: ShadingType.CLEAR };
  const altStyle = { fill: "F0EBD8", type: ShadingType.CLEAR };
  const highlightStyle = { fill: LIGHT_GOLD, type: ShadingType.CLEAR };
  const border = { style: BorderStyle.SINGLE, size: 4, color: "DDDDDD" };
  const borders = { top: border, bottom: border, left: border, right: border };

  const colWidths = [1800, 2600, 2200, 2760];

  function headerCell(text, w) {
    return new TableCell({
      borders,
      shading: headerStyle,
      width: { size: w, type: WidthType.DXA },
      margins: { top: 80, bottom: 80, left: 100, right: 100 },
      children: [new Paragraph({
        alignment: AlignmentType.LEFT,
        children: [new TextRun({ text, bold: true, size: 18, color: GOLD, font: "Arial" })]
      })]
    });
  }

  function dataCell(text, w, shade, bold = false, color = MID) {
    return new TableCell({
      borders,
      shading: shade,
      width: { size: w, type: WidthType.DXA },
      margins: { top: 80, bottom: 80, left: 100, right: 100 },
      children: [new Paragraph({
        children: [new TextRun({ text, size: 18, bold, color, font: "Arial" })]
      })]
    });
  }

  const rows = [
    new TableRow({
      children: [
        headerCell("Competitor", colWidths[0]),
        headerCell("Positioning", colWidths[1]),
        headerCell("Ad Spend", colWidths[2]),
        headerCell("Gap", colWidths[3])
      ]
    }),
    new TableRow({
      children: [
        dataCell("JECT NYC", colWidths[0], { fill: WHITE, type: ShadingType.CLEAR }),
        dataCell("Injectable lifestyle. Botox made trendy.", colWidths[1], { fill: WHITE, type: ShadingType.CLEAR }),
        dataCell("High", colWidths[2], { fill: WHITE, type: ShadingType.CLEAR }),
        dataCell("Zero skin-health or longevity narrative", colWidths[3], { fill: WHITE, type: ShadingType.CLEAR })
      ]
    }),
    new TableRow({
      children: [
        dataCell("Tribeca MedSpa", colWidths[0], { fill: LIGHT_GRAY, type: ShadingType.CLEAR }),
        dataCell("Physician authority. Est. 2005.", colWidths[1], { fill: LIGHT_GRAY, type: ShadingType.CLEAR }),
        dataCell("Moderate", colWidths[2], { fill: LIGHT_GRAY, type: ShadingType.CLEAR }),
        dataCell("No founder story. Minimal content.", colWidths[3], { fill: LIGHT_GRAY, type: ShadingType.CLEAR })
      ]
    }),
    new TableRow({
      children: [
        dataCell("Skinney MedSpa", colWidths[0], { fill: WHITE, type: ShadingType.CLEAR }),
        dataCell("Broad services, heavy discounting.", colWidths[1], { fill: WHITE, type: ShadingType.CLEAR }),
        dataCell("High", colWidths[2], { fill: WHITE, type: ShadingType.CLEAR }),
        dataCell("No premium identity. Pure price race.", colWidths[3], { fill: WHITE, type: ShadingType.CLEAR })
      ]
    }),
    new TableRow({
      children: [
        dataCell("CONTOUR Studio", colWidths[0], { fill: LIGHT_GRAY, type: ShadingType.CLEAR }),
        dataCell("Boutique Nolita. Preventive aging.", colWidths[1], { fill: LIGHT_GRAY, type: ShadingType.CLEAR }),
        dataCell("Moderate", colWidths[2], { fill: LIGHT_GRAY, type: ShadingType.CLEAR }),
        dataCell("Narrow tech stack. Limited depth.", colWidths[3], { fill: LIGHT_GRAY, type: ShadingType.CLEAR })
      ]
    }),
    new TableRow({
      children: [
        dataCell("Collagen Bar NYC", colWidths[0], highlightStyle, true, DARK),
        dataCell("Science-led collagen restoration. Biophysics founder. 15+ years.", colWidths[1], highlightStyle, true, DARK),
        dataCell("OPEN LANE", colWidths[2], { fill: GOLD, type: ShadingType.CLEAR }, true, DARK),
        dataCell("This full story is not being told at scale yet.", colWidths[3], highlightStyle, true, DARK)
      ]
    }),
  ];

  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: colWidths,
    rows
  });
}

// GROWTH TABLE
function growthTable() {
  const border = { style: BorderStyle.SINGLE, size: 4, color: "DDDDDD" };
  const borders = { top: border, bottom: border, left: border, right: border };
  const colWidths = [1680, 2560, 2560, 2560];

  function hCell(text, w, shade = DARK) {
    return new TableCell({
      borders,
      shading: { fill: shade, type: ShadingType.CLEAR },
      width: { size: w, type: WidthType.DXA },
      margins: { top: 80, bottom: 80, left: 100, right: 100 },
      children: [new Paragraph({
        alignment: AlignmentType.CENTER,
        children: [new TextRun({ text, bold: true, size: 18, color: shade === DARK ? GOLD : DARK, font: "Arial" })]
      })]
    });
  }

  function dCell(text, w, shade = WHITE, bold = false, color = MID) {
    return new TableCell({
      borders,
      shading: { fill: shade, type: ShadingType.CLEAR },
      width: { size: w, type: WidthType.DXA },
      margins: { top: 80, bottom: 80, left: 100, right: 100 },
      children: [new Paragraph({
        alignment: AlignmentType.CENTER,
        children: [new TextRun({ text, size: 18, bold, color, font: "Arial" })]
      })]
    });
  }

  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: colWidths,
    rows: [
      new TableRow({ children: [hCell("", colWidths[0]), hCell("FOUNDATION", colWidths[1]), hCell("GROWTH", colWidths[2]), hCell("SCALE", colWidths[3])] }),
      new TableRow({ children: [dCell("Spend", colWidths[0], LIGHT_GRAY, true, DARK), dCell("Entry level", colWidths[1], LIGHT_GRAY), dCell("Competitive", colWidths[2], LIGHT_GRAY), dCell("Market-leading", colWidths[3], LIGHT_GRAY)] }),
      new TableRow({ children: [dCell("Reach/mo", colWidths[0], WHITE, true, DARK), dCell("15K to 30K", colWidths[1]), dCell("40K to 80K", colWidths[2]), dCell("100K+", colWidths[3])] }),
      new TableRow({ children: [dCell("Leads/mo", colWidths[0], LIGHT_GRAY, true, DARK), dCell("8 to 20", colWidths[1], LIGHT_GRAY), dCell("25 to 55", colWidths[2], LIGHT_GRAY), dCell("60 to 120+", colWidths[3], LIGHT_GRAY)] }),
      new TableRow({ children: [dCell("Goal", colWidths[0], WHITE, true, DARK), dCell("Data + baseline", colWidths[1]), dCell("Consistent bookings", colWidths[2]), dCell("Full market presence", colWidths[3])] }),
    ]
  });
}

const doc = new Document({
  styles: {
    default: {
      document: { run: { font: "Arial", size: 22, color: MID } }
    },
    paragraphStyles: [
      {
        id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 26, bold: true, font: "Arial", color: DARK },
        paragraph: { spacing: { before: 200, after: 80 }, outlineLevel: 0 }
      },
      {
        id: "Heading2", name: "Heading 2", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 22, bold: true, font: "Arial", color: DARK },
        paragraph: { spacing: { before: 160, after: 60 }, outlineLevel: 1 }
      },
    ]
  },
  sections: [
    {
      properties: {
        page: {
          size: { width: 12240, height: 15840 },
          margin: { top: 900, right: 1080, bottom: 900, left: 1080 }
        }
      },
      children: [

        // ---- HEADER BLOCK ----
        new Paragraph({
          spacing: { before: 0, after: 0 },
          children: [new TextRun({ text: "THE LUXORA COLLECTIVE", bold: true, size: 18, color: GOLD, font: "Arial", characterSpacing: 80 })]
        }),
        new Paragraph({
          spacing: { before: 0, after: 60 },
          children: [new TextRun({ text: "Market Intelligence Preview", size: 18, color: "888888", font: "Arial", italics: true })]
        }),
        goldRule(),

        // TITLE
        new Paragraph({
          spacing: { before: 0, after: 40 },
          children: [new TextRun({ text: "Collagen Bar NYC", bold: true, size: 52, color: DARK, font: "Arial" })]
        }),
        new Paragraph({
          spacing: { before: 0, after: 60 },
          children: [new TextRun({ text: "What We Found in Your Market  |  Prepared for Diana Seo", size: 22, color: "888888", font: "Arial", italics: true })]
        }),

        // INTRO CALLOUT
        new Paragraph({
          spacing: { before: 0, after: 0 },
          border: { left: { style: BorderStyle.SINGLE, size: 20, color: GOLD, space: 10 } },
          indent: { left: 300 },
          children: [
            new TextRun({ text: "Bethany reviewed your market, your competitors, and your client feedback directly. What follows is a snapshot of what we found. The full in-depth version is reserved for your strategy call.", size: 22, italics: true, color: MID, font: "Arial" })
          ]
        }),

        spacer(160),

        // SECTION 01: Market at a Glance
        new Paragraph({
          heading: HeadingLevel.HEADING_1,
          children: [new TextRun({ text: "01  |  Your Market at a Glance", bold: true, size: 26, color: DARK, font: "Arial" })]
        }),
        thinRule(),
        spacer(80),
        statBoxes(),
        spacer(120),

        new Paragraph({
          spacing: { before: 0, after: 0 },
          children: [
            new TextRun({ text: "You are operating across four locations in Manhattan and Westchester simultaneously. More than 200 active medspa and aesthetic competitors are vying for attention in this market. ", size: 22, color: MID, font: "Arial" }),
            new TextRun({ text: "The majority are injectable-heavy, discount-driven, and broadly positioned.", size: 22, bold: true, color: DARK, font: "Arial" }),
            new TextRun({ text: " That creates significant noise, but it also creates a lane. A premium, science-led practice like Collagen Bar does not belong in that conversation, and the full analysis reveals exactly where your opening is.", size: 22, color: MID, font: "Arial" })
          ]
        }),

        spacer(160),

        // SECTION 02: What clients say
        new Paragraph({
          heading: HeadingLevel.HEADING_1,
          children: [new TextRun({ text: "02  |  What Your Clients Are Already Telling the Market", bold: true, size: 26, color: DARK, font: "Arial" })]
        }),
        thinRule(),
        spacer(80),

        new Paragraph({
          spacing: { before: 0, after: 100 },
          children: [new TextRun({ text: "We reviewed your public feedback. One phrase repeats consistently across reviews:", size: 22, color: MID, font: "Arial" })]
        }),

        // Pull quote
        new Paragraph({
          spacing: { before: 60, after: 60 },
          shading: { fill: LIGHT_GOLD, type: ShadingType.CLEAR },
          border: {
            top: { style: BorderStyle.SINGLE, size: 4, color: GOLD },
            bottom: { style: BorderStyle.SINGLE, size: 4, color: GOLD },
            left: { style: BorderStyle.NONE },
            right: { style: BorderStyle.NONE }
          },
          indent: { left: 360, right: 360 },
          alignment: AlignmentType.CENTER,
          children: [
            new TextRun({ text: '"I finally found a place that knows what they are talking about', size: 26, italics: true, bold: true, color: DARK, font: "Arial" }),
            new TextRun({ text: ' ', size: 26, font: "Arial" }),
            new TextRun({ text: "an alternative to fillers and Botox."", size: 26, italics: true, bold: true, color: GOLD, font: "Arial" })
          ]
        }),

        spacer(80),

        new Paragraph({
          spacing: { before: 0, after: 0 },
          children: [
            new TextRun({ text: "That is not a small niche. It is a growing, research-aware segment of the Manhattan market, and your competitors are not speaking to those people at all. ", size: 22, color: MID, font: "Arial" }),
            new TextRun({ text: "Your clients are pre-selling Collagen Bar for you.", size: 22, bold: true, color: DARK, font: "Arial" }),
            new TextRun({ text: " The full analysis shows what that means for acquisition strategy, and it is one of the most compelling findings in this report.", size: 22, color: MID, font: "Arial" })
          ]
        }),

        spacer(80),

        new Paragraph({
          spacing: { before: 0, after: 0 },
          children: [
            new TextRun({ text: "Your Unlimited Collagen for a Year membership at $200/month is also a retention signal worth unpacking. Clients who commit to monthly programs are the highest-lifetime-value clients in this category. ", size: 22, color: MID, font: "Arial" }),
            new TextRun({ text: "The full report shows how that infrastructure maps to a scalable revenue model.", size: 22, bold: true, color: DARK, font: "Arial" })
          ]
        }),

        // PAGE BREAK
        new Paragraph({ children: [new PageBreak()] }),

        // ---- PAGE 2 ----

        // Re-anchor with thin brand line
        new Paragraph({
          spacing: { before: 0, after: 60 },
          children: [new TextRun({ text: "THE LUXORA COLLECTIVE  |  Collagen Bar NYC Market Preview", size: 18, color: "999999", font: "Arial", italics: true })]
        }),
        thinRule("DDDDDD"),

        // SECTION 03: Competitors
        new Paragraph({
          heading: HeadingLevel.HEADING_1,
          children: [new TextRun({ text: "03  |  Who Is Competing for Your Clients Right Now", bold: true, size: 26, color: DARK, font: "Arial" })]
        }),
        thinRule(),
        spacer(80),

        new Paragraph({
          spacing: { before: 0, after: 100 },
          children: [
            new TextRun({ text: "Here is a preview of the competitive landscape. The full report includes positioning breakdowns, content strategy gaps, and specific acquisition angles for each.", size: 22, color: MID, font: "Arial" })
          ]
        }),

        competitorTable(),

        spacer(100),

        new Paragraph({
          spacing: { before: 0, after: 0 },
          shading: { fill: DARK, type: ShadingType.CLEAR },
          indent: { left: 180, right: 180 },
          children: [
            new TextRun({ text: "  Not one competitor is leading with a collagen restoration, skin-as-a-marathon, or longevity-first narrative. That lane is sitting unclaimed.  ", size: 22, bold: true, color: GOLD, font: "Arial", italics: true })
          ]
        }),

        spacer(160),

        // SECTION 04: Growth Preview
        new Paragraph({
          heading: HeadingLevel.HEADING_1,
          children: [new TextRun({ text: "04  |  What Scaled Visibility Could Look Like", bold: true, size: 26, color: DARK, font: "Arial" })]
        }),
        thinRule(),
        spacer(60),

        new Paragraph({
          spacing: { before: 0, after: 100 },
          children: [new TextRun({ text: "These are directional benchmarks based on current Manhattan market conditions, not performance guarantees. The full report includes a detailed campaign approach built around Diana's story and credentials.", size: 22, color: MID, font: "Arial" })]
        }),

        growthTable(),

        spacer(160),

        // CTA BLOCK
        new Table({
          width: { size: 9360, type: WidthType.DXA },
          columnWidths: [9360],
          rows: [
            new TableRow({
              children: [
                new TableCell({
                  borders: {
                    top: { style: BorderStyle.SINGLE, size: 6, color: GOLD },
                    bottom: { style: BorderStyle.SINGLE, size: 6, color: GOLD },
                    left: { style: BorderStyle.NONE },
                    right: { style: BorderStyle.NONE }
                  },
                  shading: { fill: LIGHT_GOLD, type: ShadingType.CLEAR },
                  margins: { top: 240, bottom: 240, left: 360, right: 360 },
                  width: { size: 9360, type: WidthType.DXA },
                  children: [
                    new Paragraph({
                      alignment: AlignmentType.CENTER,
                      spacing: { before: 0, after: 80 },
                      children: [new TextRun({ text: "This is a preview. The full picture goes deeper.", bold: true, size: 28, color: DARK, font: "Arial" })]
                    }),
                    new Paragraph({
                      alignment: AlignmentType.CENTER,
                      spacing: { before: 0, after: 100 },
                      children: [new TextRun({ text: "The complete in-depth version covers the right offer structure for your specific client profile, a campaign strategy built around Diana's credentials and press record, your membership growth path, and a clear, prioritized next step. It is designed to be walked through with your team.", size: 22, color: MID, font: "Arial" })]
                    }),
                    new Paragraph({
                      alignment: AlignmentType.CENTER,
                      spacing: { before: 0, after: 0 },
                      children: [new TextRun({ text: "Jump on a 30-minute call with Bethany to go through it together.", bold: true, size: 26, color: GOLD, font: "Arial" })]
                    }),
                  ]
                })
              ]
            })
          ]
        }),

        spacer(160),

        // FOOTER
        thinRule(GOLD),
        new Paragraph({
          alignment: AlignmentType.CENTER,
          spacing: { before: 60, after: 0 },
          children: [
            new TextRun({ text: "The Luxora Collective  |  theluxoracollective.co", size: 18, color: "999999", font: "Arial" })
          ]
        }),
      ]
    }
  ]
});

Packer.toBuffer(doc).then(buffer => {
  fs.writeFileSync('/home/claude/Collagen_Bar_Market_Preview.docx', buffer);
  console.log('Done');
});

