// GROWTH TABLE
function growthTable() {
  const border = { style: BorderStyle.SINGLE, size: 4, color: "DDDDDD" };
  const borders = { top: border, bottom: border, left: border, right: border };
  const colWidths = [1680, 2560, 2560, 2560];

  function hCell(text, w, shade = DARK) {
    return new TableCell({
      borders,
      shading: { fill: shade, type: ShadingType.CLEAR },
      width: { size: w, type: WidthType.DXA },
      margins: { top: 80, bottom: 80, left: 100, right: 100 },
      children: [new Paragraph({
        alignment: AlignmentType.CENTER,
        children: [new TextRun({ text, bold: true, size: 18, color: shade === DARK ? GOLD : DARK, font: "Arial" })]
      })]
    });
  }

  function dCell(text, w, shade = WHITE, bold = false, color = MID) {
    return new TableCell({
      borders,
      shading: { fill: shade, type: ShadingType.CLEAR },
      width: { size: w, type: WidthType.DXA },
      margins: { top: 80, bottom: 80, left: 100, right: 100 },
      children: [new Paragraph({
        alignment: AlignmentType.CENTER,
        children: [new TextRun({ text, size: 18, bold, color, font: "Arial" })]
      })]
    });
  }

  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: colWidths,
    rows: [
      new TableRow({ children: [hCell("", colWidths[0]), hCell("FOUNDATION", colWidths[1]), hCell("GROWTH", colWidths[2]), hCell("SCALE", colWidths[3])] }),
      new TableRow({ children: [dCell("Spend", colWidths[0], LIGHT_GRAY, true, DARK), dCell("Entry level", colWidths[1], LIGHT_GRAY), dCell("Competitive", colWidths[2], LIGHT_GRAY), dCell("Market-leading", colWidths[3], LIGHT_GRAY)] }),
      new TableRow({ children: [dCell("Reach/mo", colWidths[0], WHITE, true, DARK), dCell("15K to 30K", colWidths[1]), dCell("40K to 80K", colWidths[2]), dCell("100K+", colWidths[3])] }),
      new TableRow({ children: [dCell("Leads/mo", colWidths[0], LIGHT_GRAY, true, DARK), dCell("8 to 20", colWidths[1], LIGHT_GRAY), dCell("25 to 55", colWidths[2], LIGHT_GRAY), dCell("60 to 120+", colWidths[3], LIGHT_GRAY)] }),
      new TableRow({ children: [dCell("Goal", colWidths[0], WHITE, true, DARK), dCell("Data + baseline", colWidths[1]), dCell("Consistent bookings", colWidths[2]), dCell("Full market presence", colWidths[3])] }),
    ]
  });
}

